import type {
  PageLayoutProps,
  PageLayoutMainNavProps,
  PageLayoutVerticalTabBarProps,
  PageLayoutFullProps,
  PageLayoutHeaderTitleProps,
  PageLayoutMainBodyProps,
  PageLayoutSkipToContentProps,
  PageLayoutBodyContentProps,
} from "./page-layout.types";

import React, { Children, cloneElement, forwardRef, isValidElement } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { TabBar } from "@components/tab-bar";

import { PageLayoutClasses, StyledPageLayout } from "./page-layout.styles";

const PageLayoutRoot = forwardRef<HTMLDivElement, PageLayoutProps>(
  ({ className, variant = "default", children, ...props }, ref) => {
    const theme = useTheme();
    const rootClasses = clsx(PageLayoutClasses.root, className);
    return (
      <StyledPageLayout
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        variant={variant}
        {...props}
      >
        {children}
      </StyledPageLayout>
    );
  },
);

PageLayoutRoot.displayName = "PageLayout";

// slot child components
const MainNav = React.forwardRef<HTMLDivElement, PageLayoutMainNavProps>(
  ({ className, children, ...rest }, ref) => (
    <div ref={ref} className={clsx(PageLayoutClasses.mainNav, className)} {...rest}>
      {children}
    </div>
  ),
);
MainNav.displayName = "PageLayout.MainNav";

const VerticalTabBar = React.forwardRef<HTMLDivElement, PageLayoutVerticalTabBarProps>(
  ({ className, children, ...rest }, ref) => (
    <div ref={ref} className={clsx(PageLayoutClasses.verticalTabBar, className)} {...rest}>
      {children}
    </div>
  ),
);
VerticalTabBar.displayName = "PageLayout.VerticalTabBar";

const Main = React.forwardRef<HTMLElement, PageLayoutFullProps>(
  ({ className, children, pageWidth = "default", ...rest }, ref) => (
    <main
      ref={ref}
      className={clsx(
        PageLayoutClasses.main,
        {
          [PageLayoutClasses.mainWidthDefault]: pageWidth !== "fullWidth",
        },
        className,
      )}
      {...rest}
    >
      {children}
    </main>
  ),
);
Main.displayName = "PageLayout.Main";

const Header = React.forwardRef<HTMLDivElement, PageLayoutHeaderTitleProps>(
  ({ className, children, ...rest }, ref) => (
    <div ref={ref} className={clsx(PageLayoutClasses.header, className)} {...rest}>
      {children}
    </div>
  ),
);
Header.displayName = "PageLayout.Header";

const Body = React.forwardRef<HTMLDivElement, PageLayoutMainBodyProps>(
  ({ className, children, ...rest }, ref) => {
    const themedChildren = Children.map(children, (child) => {
      if (isValidElement(child) && child.type === TabBar) {
        return cloneElement(child, {
          ...child.props,
          variant: child.props.variant || "line",
        });
      }
      return child;
    });
    return (
      <div ref={ref} className={clsx(PageLayoutClasses.body, className)} {...rest}>
        {themedChildren}
      </div>
    );
  },
);
Body.displayName = "PageLayout.Body";

const BodyContent = React.forwardRef<HTMLDivElement, PageLayoutBodyContentProps>(
  ({ className, children, ...rest }, ref) => (
    <div ref={ref} className={clsx(PageLayoutClasses.bodyContent, className)} {...rest}>
      {children}
    </div>
  ),
);
BodyContent.displayName = "PageLayout.BodyContent";

// accessibility components
const SkipToContent = React.forwardRef<HTMLAnchorElement, PageLayoutSkipToContentProps>(
  ({ className, targetId, children = "Skip to content", href, ...rest }, ref) => {
    const finalHref = href || (targetId ? `#${targetId}` : undefined);
    return (
      <a
        ref={ref}
        className={clsx(PageLayoutClasses.skipToContent, className)}
        href={finalHref}
        {...rest}
      >
        {children}
      </a>
    );
  },
);
SkipToContent.displayName = "PageLayout.SkipToContent";

type PageLayoutCompoundComponent = typeof PageLayoutRoot & {
  MainNav: typeof MainNav;
  VerticalTabBar: typeof VerticalTabBar;
  Main: typeof Main;
  Header: typeof Header;
  Body: typeof Body;
  BodyContent: typeof BodyContent;
  SkipToContent: typeof SkipToContent;
};

const PageLayout = PageLayoutRoot as PageLayoutCompoundComponent;
PageLayout.MainNav = MainNav;
PageLayout.VerticalTabBar = VerticalTabBar;
PageLayout.Main = Main;
PageLayout.Header = Header;
PageLayout.Body = Body;
PageLayout.BodyContent = BodyContent;
PageLayout.SkipToContent = SkipToContent;

export default PageLayout;
